  "La QR-facture PDF est jointe automatiquement au message (démonstration : aucun envoi réel).": ["The QR-bill PDF is attached to the message automatically (demo: nothing is actually sent).", "La QR-factura en PDF se adjunta automáticamente al mensaje (demostración: no se envía nada realmente)."],
