  "Madame, Monsieur, Sauf erreur de notre part, notre facture {0} du {1} d’un montant de {2}, échue le {3}, demeure impayée à ce jour. Nous vous remercions de bien vouloir procéder à son règlement d’ici au {4}. Si votre paiement a croisé ce courrier, veuillez ne pas tenir compte de ce rappel.": ["Dear Sir or Madam, Unless we are mistaken, our invoice {0} of {1} for an amount of {2}, due on {3}, remains unpaid to date. We would be grateful if you could settle it by {4}. If your payment has crossed with this letter, please disregard this reminder.", "Señora, señor: Salvo error por nuestra parte, nuestra factura {0} del {1} por un importe de {2}, vencida el {3}, sigue pendiente de pago a la fecha. Le agradeceríamos que procediera a su pago antes del {4}. Si su pago se ha cruzado con esta carta, no tenga en cuenta este recordatorio."],
  "Madame, Monsieur, Veuillez trouver ci-joint notre facture {0} relative à : {1}. Montant : {2} TTC (dont TVA {3} % {4}) Échéance : {5} Le paiement peut être effectué au moyen de la QR-facture jointe (référence {6}).": ["Dear Sir or Madam, Please find attached our invoice {0} relating to: {1}. Amount: {2} incl. VAT (of which VAT {3} % {4}) Due date: {5} Payment can be made using the attached QR-bill (reference {6}).", "Señora, señor: Adjuntamos nuestra factura {0} relativa a: {1}. Importe: {2} IVA incluido (de los cuales IVA {3} % {4}) Vencimiento: {5} El pago puede efectuarse mediante la QR-factura adjunta (referencia {6})."],
