  "La convocation est adressée à chaque copropriétaire au moins": ["The notice is sent to each co-owner at least", "La convocatoria se envía a cada copropietario al menos"],
  "Le copropriétaire empêché peut se faire représenter au moyen d’une procuration écrite. Les documents relatifs aux points de l’ordre du jour peuvent être consultés auprès de l’administrateur.": ["A co-owner who is unable to attend may be represented by written proxy. Documents relating to the agenda items may be consulted at the administrator’s office.", "El copropietario que no pueda asistir podrá hacerse representar mediante un poder escrito. Los documentos relativos a los puntos del orden del día pueden consultarse en la oficina del administrador."],
