  "Loyers payables d’avance le 1er du mois · QR-facture": ["Rents payable in advance on the 1st of the month · QR-bill", "Alquileres pagaderos por adelantado el día 1 de cada mes · QR-factura"],
  "Loyers payables d’avance le 1er du mois · QR-facture {0}": ["Rents payable in advance on the 1st of the month · QR-bill {0}", "Alquileres pagaderos por adelantado el día 1 de cada mes · QR-factura {0}"],
  "L’administrateur": ["The administrator", "El administrador"],
  "Madame, Monsieur, Malgré notre premier rappel, le loyer de {0} (« {1} ») reste impayé à ce jour, pour un montant de {2}. Nous vous prions instamment de régulariser votre situation d’ici au {3}. Si vous rencontrez des difficultés passagères, nous vous invitons à prendre contact avec nous afin de convenir d’un arrangement.": ["Dear Sir or Madam, Despite our first reminder, the rent for {0} (“{1}”) remains unpaid to date, for an amount of {2}. We urge you to settle the matter by {3}. If you are experiencing temporary difficulties, please contact us so that we can agree on an arrangement.", "Señora, señor: Pese a nuestro primer recordatorio, el alquiler de {0} (“{1}”) sigue pendiente de pago a la fecha, por un importe de {2}. Le rogamos encarecidamente que regularice su situación antes del {3}. Si atraviesa dificultades pasajeras, lo invitamos a ponerse en contacto con nosotros para acordar una solución."],
  "Madame, Monsieur, Sauf erreur de notre part, le loyer de {0} relatif à l’objet « {1} » ne nous est pas encore parvenu (solde dû : {2}, échu le {3}). Il s’agit probablement d’un oubli : nous vous remercions de bien vouloir procéder au règlement d’ici au {4} au moyen de la QR-facture habituelle. Si votre paiement a croisé ce courrier, nous vous prions de ne pas en tenir compte.": ["Dear Sir or Madam, Unless we are mistaken, the rent for {0} relating to the property “{1}” has not yet reached us (balance due: {2}, due on {3}). This is probably an oversight: please settle it by {4} using the usual QR-bill. If your payment has crossed with this letter, please disregard it.", "Señora, señor: Salvo error por nuestra parte, el alquiler de {0} relativo al objeto “{1}” aún no nos ha llegado (saldo pendiente: {2}, vencido el {3}). Probablemente se trate de un olvido: le agradecemos que proceda al pago antes del {4} mediante la QR-factura habitual. Si su pago se ha cruzado con esta carta, no la tenga en cuenta."],
