  "RECOMMANDÉ Mise en demeure — art. 257d CO Madame, Monsieur, Nos rappels étant restés sans effet, nous constatons que le montant de {0}, correspondant au loyer de {1} pour l’objet « {2} » (bail {3}), demeure impayé. Conformément à l’art. 257d al. 1 CO, nous vous impartissons un délai de 30 jours dès réception de la présente pour vous acquitter de ce montant. À défaut de paiement intégral dans ce délai, le bailleur résiliera le bail moyennant un délai de congé de 30 jours pour la fin d’un mois (art. 257d al. 2 CO), au moyen de la formule officielle.": ["REGISTERED Formal notice — art. 257d CO Dear Sir or Madam, As our reminders have had no effect, we note that the amount of {0}, corresponding to the rent for {1} for the property “{2}” (lease {3}), remains unpaid. In accordance with art. 257d para. 1 CO, we grant you a period of 30 days from receipt of this letter to pay this amount. Failing full payment within this period, the landlord will terminate the lease with 30 days’ notice to the end of a month (art. 257d para. 2 CO), using the official form.", "CERTIFICADO Requerimiento formal — art. 257d CO Señora, señor: Al no haber surtido efecto nuestros recordatorios, constatamos que el importe de {0}, correspondiente al alquiler de {1} del objeto “{2}” (contrato {3}), sigue pendiente de pago. De conformidad con el art. 257d ap. 1 CO, le concedemos un plazo de 30 días a partir de la recepción de la presente para abonar dicho importe. De no producirse el pago íntegro en dicho plazo, el arrendador rescindirá el contrato con un preaviso de 30 días para el final de un mes (art. 257d ap. 2 CO), mediante el formulario oficial."],
