  "Bonjour, Nous vous remercions de l’intérêt porté à l’objet « {0} » et de votre dossier de candidature. Afin de pouvoir le présenter au propriétaire, il nous manque encore les documents suivants : {1} Vous pouvez nous les transmettre en réponse à ce message ou les déposer à l’agence, Place du Port 3 à Montvigne. Les dossiers complets sont traités en priorité.": ["Hello, Thank you for your interest in the property “{0}” and for your application. In order to present it to the owner, we still need the following documents: {1} You can send them to us in reply to this message or drop them off at the agency, Place du Port 3 in Montvigne. Complete applications are processed first.", "Buenos días: Le agradecemos su interés por el objeto “{0}” y su expediente de solicitud. Para poder presentarlo al propietario, aún nos faltan los siguientes documentos: {1} Puede enviárnoslos en respuesta a este mensaje o entregarlos en la agencia, Place du Port 3 en Montvigne. Los expedientes completos se tramitan con prioridad."],
  "Bonjour, Nous vous remercions sincèrement pour votre candidature concernant l’objet « {0} » ainsi que pour le temps consacré à la visite. Après examen attentif des dossiers reçus, le propriétaire a malheureusement porté son choix sur une autre candidature. Cette décision ne remet nullement en cause la qualité de votre dossier. Nous nous permettons de conserver vos coordonnées afin de vous proposer en priorité les objets correspondant à votre recherche. Nos annonces sont également disponibles sur vauclair-immobilier.ch. En vous souhaitant plein succès dans vos recherches,": ["Hello, Thank you sincerely for your application for the property “{0}” and for the time you devoted to the viewing. After careful review of the applications received, the owner has unfortunately chosen another candidate. This decision in no way calls into question the quality of your application. We would like to keep your details so that we can offer you, as a priority, properties matching your search. Our listings are also available on vauclair-immobilier.ch. Wishing you every success in your search,", "Buenos días: Le agradecemos sinceramente su solicitud para el objeto “{0}” y el tiempo dedicado a la visita. Tras un examen atento de los expedientes recibidos, el propietario ha optado lamentablemente por otra solicitud. Esta decisión no cuestiona en absoluto la calidad de su expediente. Nos permitimos conservar sus datos para proponerle con prioridad los objetos que correspondan a su búsqueda. Nuestros anuncios también están disponibles en vauclair-immobilier.ch. Le deseamos mucho éxito en su búsqueda,"],
