  "du coût de remise en état.": ["of the repair cost.", "del costo de reparación."],
  "du plan de l’objet. À la sortie, il est comparé à l’état des lieux d’entrée : seuls les dégâts dépassant l’usure normale sont imputables au locataire (art. 267 CO), après déduction de la vétusté.": ["of the property plan. At move-out, it is compared with the move-in report: only damage beyond normal wear and tear is chargeable to the tenant (art. 267 CO), after deduction for depreciation.", "del plano del objeto. A la salida, se compara con el acta de inspección de entrada: solo los daños que superen el desgaste normal son imputables al inquilino (art. 267 CO), previa deducción de la vetustez."],
