  "Préavis de 3 mois pour la fin d’un mois, sauf décembre (usages locatifs vaudois). Résiliation par le bailleur sur formule officielle (art. 266l CO).": ["3 months’ notice to the end of a month, except December (Vaud tenancy customs). Termination by the landlord on the official form (art. 266l CO).", "Preaviso de 3 meses para el final de un mes, excepto diciembre (usos locativos de Vaud). Rescisión por el arrendador mediante formulario oficial (art. 266l CO)."],
  "qui suivent la réception de la chose auprès de la Commission de conciliation en matière de baux à loyer du district de Lavaux-Oron, s’il estime ce montant abusif au sens des art. 269 et 269a CO (art. 270 CO).": ["following receipt of the property, before the Conciliation Commission for tenancy matters of the Lavaux-Oron district, if they consider this amount excessive within the meaning of art. 269 and 269a CO (art. 270 CO).", "siguientes a la recepción del objeto ante la Comisión de conciliación en materia de arrendamientos del distrito de Lavaux-Oron, si considera dicho importe abusivo en el sentido de los art. 269 y 269a CO (art. 270 CO)."],
