  "Un refus courtois et personnalisé — le dossier sera marqué « Refusé ».": ["A courteous, personalised rejection — the application will be marked “Declined”.", "Un rechazo cortés y personalizado — el expediente se marcará como “Rechazado”."],
  "Un état des lieux contradictoire est établi à l’entrée et à la sortie. Le locataire conclut une assurance responsabilité civile ménage. Les animaux de compagnie sont soumis à l’accord écrit du bailleur. La formule officielle de notification du loyer initial fait partie intégrante du présent contrat.": ["A joint inspection report is drawn up at move-in and move-out. The tenant takes out household liability insurance. Pets are subject to the landlord’s written consent. The official initial rent notification form forms an integral part of this contract.", "Se levanta un acta de inspección contradictoria a la entrada y a la salida. El inquilino contrata un seguro de responsabilidad civil del hogar. Los animales de compañía están sujetos al consentimiento escrito del arrendador. El formulario oficial de notificación del alquiler inicial forma parte integrante del presente contrato."],
  "Un état des lieux de {0} est déjà ouvert pour ce bail.": ["A {0} inspection report is already open for this lease.", "Ya hay un acta de inspección de {0} abierta para este contrato."],
