  ", exigible à la signature du bail.": [", payable on signature of the lease.", ", exigible a la firma del contrato."],
  ", prélevés mensuellement lors du décompte au propriétaire.": [", deducted monthly in the owner statement.", ", deducidos mensualmente en la liquidación al propietario."],
  ", sauf convention contraire": [", unless otherwise agreed", ", salvo pacto en contrario"],
  ", soit {0},": [", i.e. {0},", ", es decir, {0},"],
  ", soit à titre indicatif {0} HT. Elle est exigible lors de la signature de l’acte authentique de vente et payable par le notaire instrumentant. Elle reste due pour toute vente conclue dans les 12 mois suivant l’échéance avec un acquéreur présenté par le mandataire.": [", i.e. for information {0} excl. VAT. It is payable on signature of the notarised deed of sale and paid by the officiating notary. It remains due for any sale concluded within 12 months of expiry with a buyer introduced by the agent.", ", es decir, a título indicativo {0} sin IVA. Es exigible a la firma de la escritura pública de compraventa y la abona el notario actuante. Sigue siendo debida por toda venta celebrada en los 12 meses siguientes al vencimiento con un comprador presentado por el mandatario."],
  ", sous réserve des fors impératifs.": [", subject to mandatory jurisdictions.", ", sin perjuicio de los fueros imperativos."],
  ", {0}, {1} Montvigne, parcelle {2} du registre foncier de Lavaux.": [", {0}, {1} Montvigne, plot {2} in the Lavaux land register.", ", {0}, {1} Montvigne, parcela {2} del registro de la propiedad de Lavaux."],
  ". Pendant sa durée, le mandant s’interdit de confier la vente à un autre intermédiaire et s’engage à adresser au mandataire tout amateur qui le contacterait directement. Une vente conclue directement par le mandant pendant la durée du mandat donne droit à la pleine commission.": [". During its term, the principal undertakes not to entrust the sale to any other intermediary and to refer to the agent any prospective buyer who contacts them directly. A sale concluded directly by the principal during the term of the mandate gives entitlement to the full commission.", ". Durante su vigencia, el mandante se compromete a no confiar la venta a ningún otro intermediario y a remitir al mandatario cualquier interesado que se ponga en contacto directamente con él. Una venta celebrada directamente por el mandante durante la vigencia del mandato da derecho a la comisión íntegra."],
  ". Toute offre sera transmise au mandant, seul habilité à l’accepter. Le mandataire n’est pas autorisé à conclure au nom du mandant.": [". Any offer will be forwarded to the principal, who alone is authorised to accept it. The agent is not authorised to conclude on the principal’s behalf.", ". Toda oferta se transmitirá al mandante, único facultado para aceptarla. El mandatario no está autorizado a contratar en nombre del mandante."],
  ". À défaut de résiliation écrite trente jours avant l’échéance, il est reconduit tacitement de trois mois en trois mois.": [". Unless terminated in writing thirty days before expiry, it is tacitly renewed for successive three-month periods.", ". Salvo rescisión por escrito treinta días antes del vencimiento, se prorroga tácitamente por periodos de tres meses."],
  "8.1 % en sus · {0} TTC": ["8.1 % VAT on top · {0} incl. VAT", "8,1 % de IVA adicional · {0} IVA incl."],
  ": il apparaît dans la salle d’attente de l’agence sur la carte vivante jusqu’à sa signature. Taux usuels : vente exclusive {0} %, vente simple {1} %, gérance {2} %.": [": it appears in the agency’s waiting room on the live map until it is signed. Standard rates: exclusive sale {0} %, simple sale {1} %, management {2} %.", ": aparece en la sala de espera de la agencia en el mapa vivo hasta su firma. Tasas habituales: venta exclusiva {0} %, venta simple {1} %, administración {2} %."],
