  "Jours restants": ["Days remaining", "Días restantes"],
  "La résiliation est notifiée par écrit au mandant. Pour une vente conclue dans les 12 mois avec un acquéreur présenté par l’agence, la commission reste due (clause de suite).": ["Termination is notified to the principal in writing. For a sale concluded within 12 months with a buyer introduced by the agency, the commission remains due (follow-on clause).", "La rescisión se notifica por escrito al mandante. Para una venta celebrada en los 12 meses con un comprador presentado por la agencia, la comisión sigue siendo debida (cláusula de seguimiento)."],
  "Le for juridique est à Lausanne": ["The place of jurisdiction is Lausanne", "El fuero jurídico está en Lausana"],
  "Le loyer net est fixé à": ["The net rent is set at", "El alquiler neto se fija en"],
  "Le mandant confie au mandataire, qui l’accepte, le mandat de {0} l’objet suivant :": ["The principal entrusts the agent, who accepts, with the mandate to {0} the following property:", "El mandante confía al mandatario, que lo acepta, el mandato de {0} el siguiente objeto:"],
  "Le mandat est créé": ["The mandate is created", "Se crea el mandato"],
  "Le mandat prend effet le": ["The mandate takes effect on", "El mandato entra en vigor el"],
  "Le mandataire": ["The agent", "El mandatario"],
  "Le mandataire est seul habilité à représenter le mandant auprès des locataires, des entreprises et des autorités pour les actes de gestion courante.": ["The agent alone is authorised to represent the principal vis-à-vis tenants, companies and authorities for day-to-day management matters.", "El mandatario es el único facultado para representar al mandante ante los inquilinos, las empresas y las autoridades en los actos de gestión ordinaria."],
  "Le mandataire s’engage à agir avec diligence et loyauté, à assurer la diffusion de l’objet (portails, site, fichier clients), à organiser et accompagner les visites, et à rendre compte régulièrement de son activité. Les frais de publicité usuels sont à sa charge{0}.": ["The agent undertakes to act with diligence and loyalty, to market the property (portals, website, client database), to organise and accompany viewings, and to report regularly on their activity. Standard advertising costs are borne by the agent{0}.", "El mandatario se compromete a actuar con diligencia y lealtad, a difundir el objeto (portales, web, base de clientes), a organizar y acompañar las visitas y a informar regularmente de su actividad. Los gastos de publicidad habituales corren a su cargo{0}."],
  "Le prix de vente est fixé d’entente entre les parties à": ["The sale price is set by agreement between the parties at", "El precio de venta se fija de común acuerdo entre las partes en"],
  "Le présent contrat est régi par le droit suisse, notamment les articles 412 et suivants du Code des obligations.": ["This contract is governed by Swiss law, in particular articles 412 et seq. of the Code of Obligations.", "El presente contrato se rige por el derecho suizo, en particular por los artículos 412 y siguientes del Código de Obligaciones."],
  "Le présent mandat est": ["This mandate is", "El presente mandato es"],
  "Le présent mandat n’est pas exclusif. Le mandant reste libre de confier l’objet à d’autres intermédiaires ; la commission n’est due qu’au courtier dont l’activité a été la cause de la conclusion.": ["This mandate is not exclusive. The principal remains free to entrust the property to other intermediaries; the commission is only due to the broker whose activity led to the conclusion.", "El presente mandato no es exclusivo. El mandante es libre de confiar el objeto a otros intermediarios; la comisión solo se debe al agente cuya actividad haya dado lugar a la celebración."],
