  "Cher Maître, Nous vous confirmons la vente de {0} ({1}) au prix de {2}, entre {3} (vendeur) et {4} (acquéreur). {5}Vous trouverez en annexe l’extrait du registre foncier, les pièces d’identité des parties et l’attestation de financement. Nous vous saurions gré de bien vouloir prévoir le versement de notre commission ({6} HT, TVA 8.1 % en sus) lors de la signature.{7}": ["Dear Notary, We confirm the sale of {0} ({1}) at the price of {2}, between {3} (seller) and {4} (buyer). {5}Please find attached the land register extract, the parties’ identity documents and the financing certificate. We would be grateful if you could arrange payment of our commission ({6} excl. VAT, plus 8.1 % VAT) at the signing.{7}", "Estimado notario: Le confirmamos la venta de {0} ({1}) al precio de {2}, entre {3} (vendedor) y {4} (comprador). {5}Adjuntamos el extracto del registro de la propiedad, los documentos de identidad de las partes y el certificado de financiación. Le agradeceríamos que previera el pago de nuestra comisión ({6} sin IVA, más 8,1 % de IVA) en el momento de la firma.{7}"],
