  "Posée au-dessus des terrasses de Lavaux, la Villa Horizon s’ouvre entièrement sur le Léman et les Alpes. Architecture de béton clair et de chêne, piscine à débordement, volumes généreux et lumière traversante.": ["Set above the Lavaux terraces, Villa Horizon opens entirely onto Lake Geneva and the Alps. Pale concrete and oak architecture, infinity pool, generous volumes and light from both sides.", "Situada sobre las terrazas de Lavaux, Villa Horizon se abre por completo al lago Lemán y a los Alpes. Arquitectura de concreto claro y roble, piscina infinita, volúmenes generosos y luz natural por ambos lados."],
